floor_fn:
"""
    Indent a string by adding indent after each newline.
    :param string: The string to indent
    :param indent: The string to use as indentation
    :param include_first: Also indent the first line of the string (before the first newline)
    :param include_last: If the string ends on a newline, also add an indent after that.
    :return: A new string.
    """
def indent_string(
    string: Any,
    indent: Any = '  ',
    include_first: Any = True,
    include_last: Any = False
) -> object {
    base = string.replace('\n', ('\n' + indent));
    if include_first {
        base = indent + base;
    }
    if (not include_last and base.endswith(('\n' + indent))) {
        base = base[:-len(indent)];
    }
    return base;
}

test_blocks:
test "t0" {
    assert (indent_string("foo\nbar\nbaz") == "  foo\n  bar\n  baz");;
}

test "t1" {
    assert (
        indent_string("Hello, world!\n" "How's it going?")
        == "  Hello, world!\n" "  How's it going?"
    );;
}

test "t2" {
    assert (
        indent_string("One line of text.\nAnd a second line.\n")
        == "  One line of text.\n  And a second line.\n"
    );;
}

test "t3" {
    assert (
        indent_string("This is a multi-line string\n" "This is the second line")
        == "  This is a multi-line string\n  This is the second line"
    );;
}

test "t4" {
    assert (indent_string("One line of text.") == "  One line of text.");;
}
